handlers.reloadSearchGrid:
function reloadSearchGrid(event) {
			var intCode = $("#gs_intCode").val();
			if($("#fromUpdDate").val() != "" && $("#toUpdDate").val() != ""){

				var retVal = $.ajax({
					url : "validateDateRange",

					type : "POST",
					data : {
				  		fromDateValue : $("#fromUpdDate").val(),
				    	toDateValue : $("#toUpdDate").val(),
						fieldName : "Txn "
					},
						dataType : "json",
						async : false
				}).responseText;
				retVal = jQuery.parseJSON(retVal);
				if(retVal != null){
					if(retVal.jsonMessage == null){

					} else {
						window.parent.showAlert(retVal.jsonMessage);
						event.preventDefault();
						return false;
					}
				}	
			}
			var retVal = $("#transmitDataTable").jqGrid('setGridParam', {
				datatype : 'json',
				page : 1,
				postData : {
					documentNo		:$("#gs_documentNo").val(),
					documentType	:$("#gs_documentType").val(),
					status			:$("#gs_status").val(),
					errorMessage	:$("#gs_errorMessage").val(),
					fromUpdDate		:$("#fromUpdDate").val(),
					toUpdDate		:$("#toUpdDate").val(),
					clientId		:$("#gs_clientId").val(),
					referenceNo		:$("#gs_referenceNo").val(),
					outputKey		:$("#gs_outputKey").val(),
					lastSavedCode	:$("#gs_lastSavedCode").val(),
					totalexecTime	:$("#gs_totalexecTime").val(),
					refChannelOrderNo :$("#gs_refChannelOrderNo").val(),
					invoiceNumber	:$("#gs_invoiceNumber").val(),
					storeCode		:$("#gs_storeCode").val(),
					extLocCode		:$("#gs_extLocCode").val(),
					storeName		:$("#gs_storeName").val(),
					fromInvoiceDate	:$("#fromInvoiceDate").val(),
					toInvoiceDate	:$("#toInvoiceDate").val(),
					fromClosedDate  :$("#fromClosedDate").val(),
					toClosedDate  	:$("#toClosedDate").val(),
					REQ_SEARCH_FLAG : true
				},
				url : "fetchPosIntData",
				search : true				
			}).trigger('reloadGrid');
		}

